ALTER TABLE "email_delivery" ADD CONSTRAINT "email_source_shape_ck" CHECK ((case when "email_delivery"."purpose" in ('member_invitation','owner_invitation') then "email_delivery"."source"=jsonb_build_object('kind','invitation','tenantId',"email_delivery"."tenant_id"::text,'invitationId',"email_delivery"."invitation_id"::text) when "email_delivery"."purpose"='password_reset' then "email_delivery"."source"=jsonb_build_object('kind','password_reset','userId',"email_delivery"."source_user_id",'verificationId',"email_delivery"."source"->>'verificationId') and length("email_delivery"."source"->>'verificationId') between 1 and 256 when "email_delivery"."purpose"='email_verification' then "email_delivery"."source"=jsonb_build_object('kind','email_verification','userId',"email_delivery"."source_user_id",'tokenDigest',"email_delivery"."source"->>'tokenDigest') and "email_delivery"."source"->>'tokenDigest' ~ '^[a-f0-9]{64}$' else false end) is true);